    def cnt_pre(x, u):
        return Sum([If(a[j] == x, 1, 0) for j in range(u + 1)])

    M = cnt_full(r)
    conds = []

    # r is an element of the array
    conds.append(Or([r == a[i] for i in range(N)]))

    # r occurs at least as often as every element of the array
    for k in range(N):
        conds.append(cnt_full(a[k]) <= M)

    # Tie-break: for every value v with maximal count M, the M-th occurrence
    # of r comes strictly before the M-th occurrence of v. At the position j
    # where v reaches its M-th occurrence, r must already have M occurrences.
    for k in range(N):
        for j in range(N):
            conds.append(
                Implies(
                    And(
                        a[j] == a[k],
                        cnt_pre(a[k], j) == cnt_full(a[k]),
                        cnt_full(a[k]) == M,
                    ),
                    cnt_pre(r, j) == M,
                )
            )

    return And(conds)
